/* @autogenerated */
package net.civeira.phylax.common.value.importation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalTime;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.Optional;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullAndEmptySource;
import org.junit.jupiter.params.provider.ValueSource;

import net.civeira.phylax.common.value.validation.ConstraintFailList;

@DisplayName("DateLoad")
class DateLoadUnitTest {
  private static final ZoneId UTC = ZoneOffset.UTC;
  private static final LocalDate DAY = LocalDate.of(2025, 12, 16);

  @Nested
  @DisplayName("toLocalDate")
  class ToLocalDate {

    @ParameterizedTest(name = "\"{0}\"")
    @ValueSource(strings = {"2025-12-16", "16/12/2025", " 16-12-2025 ", "20251216"})
    @DisplayName("Should parse the supported text formats")
    void shouldParseTextFormats(String value) {
      ConstraintFailList fails = new ConstraintFailList();
      assertEquals(Optional.of(DAY), DateLoad.toLocalDate(UTC, "day", value, fails));
      assertTrue(fails.isEmpty());
    }

    @Test
    @DisplayName("Should parse Excel serials and epoch seconds or millis")
    void shouldParseNumericValues() {
      ConstraintFailList fails = new ConstraintFailList();
      long seconds = DAY.atStartOfDay(UTC).toEpochSecond();
      assertEquals(Optional.of(DAY), DateLoad.toLocalDate(UTC, "day", "46007.75", fails));
      assertEquals(Optional.of(DAY),
          DateLoad.toLocalDate(UTC, "day", Long.toString(seconds), fails));
      assertEquals(Optional.of(DAY),
          DateLoad.toLocalDate(UTC, "day", Long.toString(seconds * 1000), fails));
      assertEquals(Optional.of(LocalDate.of(1969, 12, 31)),
          DateLoad.toLocalDate(UTC, "day", "-5", fails));
      assertTrue(fails.isEmpty());
    }

    @ParameterizedTest(name = "\"{0}\"")
    @NullAndEmptySource
    @ValueSource(strings = {"  "})
    @DisplayName("Should report missing values as NOT_NULL")
    void shouldReportMissingValues(String value) {
      ConstraintFailList fails = new ConstraintFailList();
      assertTrue(DateLoad.toLocalDate(UTC, "day", value, fails).isEmpty());
      assertTrue(fails.includeCode("NOT_NULL"));
    }

    @ParameterizedTest(name = "\"{0}\"")
    @ValueSource(strings = {"yesterday", "99999999999999999999"})
    @DisplayName("Should report unparseable values as INVALID_DATE")
    void shouldReportInvalidValues(String value) {
      ConstraintFailList fails = new ConstraintFailList();
      assertTrue(DateLoad.toLocalDate(UTC, "day", value, fails).isEmpty());
      assertTrue(fails.includeCode("INVALID_DATE"));
    }
  }

  @Nested
  @DisplayName("toOffsetDateTime")
  class ToOffsetDateTime {
    private final OffsetDateTime expected =
        OffsetDateTime.of(DAY, LocalTime.of(10, 15, 30), ZoneOffset.ofHours(1));

    @ParameterizedTest(name = "\"{0}\"")
    @ValueSource(strings = {"2025-12-16T10:15:30+01:00", "2025-12-16T10:15:30+01:00[Europe/Madrid]",
        "2025-12-16 10:15:30+01:00", "16/12/2025 10:15:30+01:00"})
    @DisplayName("Should parse the supported text formats with offset")
    void shouldParseTextFormats(String value) {
      ConstraintFailList fails = new ConstraintFailList();
      assertEquals(Optional.of(expected), DateLoad.toOffsetDateTime(UTC, "at", value, fails));
      assertTrue(fails.isEmpty());
    }

    @Test
    @DisplayName("Should parse a plain date as the start of the day in the given zone")
    void shouldParsePlainDate() {
      ConstraintFailList fails = new ConstraintFailList();
      assertEquals(Optional.of(DAY.atStartOfDay(UTC).toOffsetDateTime()),
          DateLoad.toOffsetDateTime(UTC, "at", "2025-12-16", fails));
    }

    @Test
    @DisplayName("Should parse Excel serials and epoch seconds or millis")
    void shouldParseNumericValues() {
      ConstraintFailList fails = new ConstraintFailList();
      Instant instant = expected.toInstant();
      assertEquals(Optional.of(OffsetDateTime.of(DAY, LocalTime.of(6, 0), ZoneOffset.UTC)),
          DateLoad.toOffsetDateTime(UTC, "at", "46007.25", fails));
      assertEquals(Optional.of(instant.atOffset(ZoneOffset.UTC)),
          DateLoad.toOffsetDateTime(UTC, "at", Long.toString(instant.getEpochSecond()), fails));
      assertEquals(Optional.of(instant.atOffset(ZoneOffset.UTC)),
          DateLoad.toOffsetDateTime(UTC, "at", Long.toString(instant.toEpochMilli()), fails));
      assertTrue(fails.isEmpty());
    }

    @ParameterizedTest(name = "\"{0}\"")
    @NullAndEmptySource
    @ValueSource(strings = {"  "})
    @DisplayName("Should report missing values as NOT_NULL")
    void shouldReportMissingValues(String value) {
      ConstraintFailList fails = new ConstraintFailList();
      assertTrue(DateLoad.toOffsetDateTime(UTC, "at", value, fails).isEmpty());
      assertTrue(fails.includeCode("NOT_NULL"));
    }

    @ParameterizedTest(name = "\"{0}\"")
    @ValueSource(strings = {"tomorrow", "99999999999999999999"})
    @DisplayName("Should report unparseable values as INVALID_DATETIME")
    void shouldReportInvalidValues(String value) {
      ConstraintFailList fails = new ConstraintFailList();
      assertTrue(DateLoad.toOffsetDateTime(UTC, "at", value, fails).isEmpty());
      assertTrue(fails.includeCode("INVALID_DATETIME"));
    }
  }
}
